"""Glossário estático de nomes oficiais do PCASP (Item/Subitem — nível 6-7).

A MSC do SICONFI publica saldo por conta PCASP mas **não publica o nome da conta**: o
código vem cru (9 dígitos) e cerca de 90% das folhas de nível 6-7 (Item/Subitem) ficam sem
descrição autoritativa em ``gold.dim_conta_pcasp`` (a única fonte de nome hoje é a DCA, que
só nomeia até o nível 5 na prática). Este módulo fecha a lacuna com o catálogo oficial.

**Fonte:** Secretaria do Tesouro Nacional — "Plano de Contas Aplicado ao Setor Público
(PCASP) — Estendido", publicado no Tesouro Transparente (aba "PCASP 2024"), publicação
"Plano de Contas Aplicado ao Setor Público (PCASP) - Estendido - 2024" (buscar por este
título em tesourotransparente.gov.br/publicacoes); arquivo baixado de
thot-arquivos.tesouro.gov.br/publicacao/47458 (planilha .xlsx, 950 KB).

**Recorte** (documentado para quando a portaria mudar de versão — risco já previsto na
ficha da Sprint D1): contas de nível 6 (Item) e 7 (Subitem), status "Ativa", das classes
1-4 (Ativo, Passivo e Patrimônio Líquido, VPD, VPA — as únicas que aparecem na MSC
Patrimonial/Variações que este explorador exibe), aplicáveis a Município **ou** Estado
(coluna "Utilizada por Municípios"/"Utilizada por Estados e DF" = "Sim"). Data de obtenção:
2026-08-05. **Contas de classes 5-8 (controles orçamentários/compensação) não estão aqui**
porque não aparecem na MSC Patrimonial ingerida por esta plataforma; se isso mudar, gere
o glossário de novo com o mesmo filtro sem a restrição de classe.

Gerado por script único (não versionado) a partir da planilha oficial — ver o cabeçalho
acima para reproduzir. Nomes normalizados de CAIXA ALTA para capitalização padrão pt-BR
(conectivos como "de"/"da"/"em" em minúsculas; siglas do vocabulário fiscal preservadas).

Uso: :func:`app.modules.accounting.pcasp_glossario.nome_oficial`.
"""

from __future__ import annotations

